export type PaycheckRouterPluginPdas = {
  router: typeof findRouterPda;
  authority: typeof findAuthorityPda;
  config: typeof findConfigPda;
  asset: typeof findAssetPda;
};

export type PaycheckRouterPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function paycheckRouterProgram() {
  return <T extends PaycheckRouterPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { paycheckRouter: PaycheckRouterPlugin }> => {
    return extendClient(client, {
      paycheckRouter: <PaycheckRouterPlugin>{
        accounts: {
          asset: addSelfFetchFunctions(client, getAssetCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          paycheck: addSelfFetchFunctions(client, getPaycheckCodec()),
          router: addSelfFetchFunctions(client, getRouterCodec()),
        },
        instructions: {
          cancelLeg: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelLegInstructionAsync(input),
            ),
          closePaycheck: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClosePaycheckInstruction(input),
            ),
          closeRouter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseRouterInstructionAsync(input),
            ),
          convertHolding: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getConvertHoldingInstructionAsync(input),
            ),
          createRouter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateRouterInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          emergencyPause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEmergencyPauseInstructionAsync(input),
            ),
          executeLeg: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteLegInstructionAsync(input),
            ),
          executeLegOwner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteLegOwnerInstructionAsync(input),
            ),
          executePrestockLeg: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecutePrestockLegInstructionAsync(input),
            ),
          expireLeg: (input) =>
            addSelfPlanAndSendFunctions(client, getExpireLegInstruction(input)),
          initializeConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConfigInstructionAsync(input),
            ),
          recordPaycheck: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordPaycheckInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          setAssetStatus: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetAssetStatusInstructionAsync(input),
            ),
          setGlobalPause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetGlobalPauseInstructionAsync(input),
            ),
          setRouterPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetRouterPausedInstructionAsync(input),
            ),
          skipInflow: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSkipInflowInstruction(input),
            ),
          swapGuarded: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSwapGuardedInstructionAsync(input),
            ),
          syncWatermark: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSyncWatermarkInstruction(input),
            ),
          updateConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateConfigInstructionAsync(input),
            ),
          updateRouter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateRouterInstructionAsync(input),
            ),
          upsertAsset: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpsertAssetInstructionAsync(input),
            ),
        },
        pdas: {
          router: findRouterPda,
          authority: findAuthorityPda,
          config: findConfigPda,
          asset: findAssetPda,
        },
        identifyAccount: identifyPaycheckRouterAccount,
        identifyInstruction: identifyPaycheckRouterInstruction,
        parseInstruction: parsePaycheckRouterInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
